import { describe, it, expect } from "vitest";
import { quote, claim } from "./claim-office.js";

describe("Claim Office - quote: base premiums", () => {
  it.todo("should charge only the 5G processing fee for an empty item list");
  it.todo("should charge 100G base premium plus fee for a single sword");
  it.todo("should charge 60G base premium plus fee for a single amulet");
  it.todo("should charge 80G base premium plus fee for a single staff");
  it.todo("should charge 40G base premium plus fee for a single potion");
  it.todo("should charge 25G base premium plus fee for a single rune");
  it.todo("should charge 25G base premium plus fee for a single moonstone");
  it.todo("should sum the base premiums of several different main items");
});

describe("Claim Office - quote: component blocks", () => {
  it.todo("should charge 50G base premium for 2 runes (no block)");
  it.todo("should charge 60G base premium for exactly 3 runes (block applies)");
  it.todo("should charge 100G base premium for 4 runes (no block for the remainder)");
  it.todo("should charge 175G base premium for 7 runes (one block plus 4 singles)");
  it.todo("should charge 75G base premium for 2 runes and 1 moonstone (different types do not form a block)");
  it.todo("should charge 120G base premium for 3 runes and 3 moonstones (two separate blocks)");
});

describe("Claim Office - quote: item-level modifiers", () => {
  it.todo("should add a 50% surcharge on a cursed item's base premium");
  it.todo("should add a 30% surcharge for an item with enchantment exactly 5");
  it.todo("should not add the high-enchantment surcharge for an item with enchantment 4");
  it.todo("should add both surcharges for an item that is cursed and enchantment >= 5");
  it.todo("should apply the cursed surcharge only to the cursed item's base premium, not the policy total");
});

describe("Claim Office - quote: policy-level modifiers", () => {
  it.todo("should apply a 10% first insurance surcharge on the policy base premium");
  it.todo("should apply a 20% loyalty discount for a customer with exactly 2 years with MHPCO");
  it.todo("should not apply the loyalty discount for a customer with fewer than 2 years");
  it.todo("should apply a 15% follow-up discount on the customer's second and later contracts");
  it.todo("should not apply the follow-up discount on the customer's first contract");
  it.todo("should add the 5G processing fee at the very end, after all other modifiers");
});

describe("Claim Office - quote: rounding", () => {
  it.todo("should round the final premium up to a whole G");
});

describe("Claim Office - quote: integration", () => {
  it.todo("should charge 165G for a newcomer's cursed steel sword with enchantment 3");
  it.todo("should charge 160G for a 3-year customer's second contract with a cursed sword of enchantment 7");
});

describe("Claim Office - quote: errors", () => {
  it.todo("should reject a quote containing an item with an unknown type");
});

describe("Claim Office - claim: insurance sum and cap", () => {
  it.todo("should cap the policy payout at twice the insurance sum of a single sword");
  it.todo("should sum the insurance values of several items to derive the cap");
  it.todo("should base the cap on unmodified insurance values, ignoring premium modifiers");
  it.todo("should base the cap on the full component insurance values, ignoring the block discount");
});

describe("Claim Office - claim: standard reimbursement", () => {
  it.todo("should pay the damage amount minus the 100G deductible for a regular sword");
  it.todo("should pay the damage amount minus the 100G deductible for a damaged rune");
  it.todo("should apply the 100G deductible once per damage entry when several items are damaged");
});

describe("Claim Office - claim: special clauses", () => {
  it.todo("should reimburse 50% of the damage before the deductible for enchantment exactly 8");
  it.todo("should reimburse dragon material fully before the deductible");
  it.todo("should let the 50% enchantment rule win when both the enchantment and dragon clauses apply");
  it.todo("should reimburse a dragon-material item with enchantment below 8 in full before the deductible");
});

describe("Claim Office - claim: cap depletion", () => {
  it.todo("should report the remaining cap after a claim");
  it.todo("should reduce a payout to the remaining cap when the cap is exhausted by successive claims");
});

describe("Claim Office - claim: rounding", () => {
  it.todo("should round the final payout down to a whole G");
});

describe("Claim Office - claim: multiple items of the same type", () => {
  it.todo("should treat two damage entries of the same item type as separate damages with their own deductibles");
});

describe("Claim Office - claim: errors", () => {
  it.todo("should reject a claim with a damage entry for an item type not covered by the policy");
  it.todo("should reject a claim with more damage entries of a type than the policy insures");
  it.todo("should reject a claim with a negative damage amount");
});

describe("Claim Office - CLI", () => {
  it.todo("should read a scenario from stdin and write a results array to stdout");
  it.todo("should return one result per step in the same order as the input steps");
  it.todo("should return a premium for a quote step and a payout with remainingCap for a claim step");
  it.todo("should resolve a claim step's policy field to the quote step at that zero-based index");
  it.todo("should exit with a non-zero status and write to stderr for an unknown item type in a quote");
  it.todo("should exit with a non-zero status and write to stderr for a damage entry not covered by the policy");
  it.todo("should exit with a non-zero status and write to stderr for a negative damage amount");
  it.todo("should write no results to stdout when the scenario is rejected");
});
